<template>
    <div class="card">
        <slot name="start"></slot>
        <div
            v-if="$slots.header || icon || title || cardActions?.length"
            class="card-header"
            :class="[cardHeaderClass, { 'card-header-icon': icon, 'has-card-actions': cardActions?.length }]"
        >
            <div class="card-icon" v-if="icon">
                <i class="material-icons">{{ icon }}</i>
            </div>
            <h4 v-if="title" class="card-title">{{ title }}</h4>
            <div v-if="cardActions?.length" class="card-action-group d-flex align-items-center">
                <template v-for="action in cardActions" :key="action.id ?? action.label">
                    <div v-if="Array.isArray(action.items) && action.items.length">
                        <button
                            type="button"
                            class="btn-icon card-action-trigger"
                            :aria-label="action.label"
                            :disabled="action.disabled"
                            aria-expanded="false"
                            data-bs-toggle="menu"
                            data-bs-placement="bottom-end"
                        >
                            <i class="material-icons" aria-hidden="true">{{ action.icon || 'more_vert' }}</i>
                        </button>
                        <div class="menu">
                            <component
                                v-for="item in action.items"
                                :key="item.id ?? item.label"
                                :is="actionElement(item)"
                                v-bind="actionAttributes(item)"
                                class="menu-item"
                                @click="item.onClick?.($event)"
                            >
                                <i v-if="item.icon" class="material-icons menu-item-icon" aria-hidden="true">{{ item.icon }}</i>
                                {{ item.label }}
                            </component>
                        </div>
                    </div>
                    <component
                        v-else-if="action.href || action.onClick"
                        :is="actionElement(action)"
                        v-bind="actionAttributes(action)"
                        class="card-action-trigger"
                        :class="action.icon ? 'btn-icon' : 'btn-outline btn-sm'"
                        :aria-label="action.icon ? action.label : undefined"
                        @click="action.onClick?.($event)"
                    >
                        <i v-if="action.icon" class="material-icons" aria-hidden="true">{{ action.icon }}</i>
                        <template v-else>{{ action.label }}</template>
                    </component>
                </template>
            </div>
            <slot name="header"></slot>
        </div>
        <div v-if="$slots.default" class="card-body" :class="cardBodyClass">
            <slot />
        </div>
        <!-- if has content for footer slot -->
        <div class="card-footer" v-if="$slots.footer">
            <slot name="footer"></slot>
        </div>
        <slot name="end"></slot>
    </div>
</template>

<script>
import { Link } from '@inertiajs/vue3';

export default {
    name: "Card",
    props: {
        title: {
            type: String,
            required: false,
        },
        cardActions: {
            type: Array,
            required: false,
            default: () => [],
        },
        icon: {
            type: String,
            required: false,
            default: null,
        },
        cardHeaderClass: {
            type: String,
            required: false,
            default: null,
        },
        cardBodyClass: {
            type: String,
            default: null,
        },
    },
    methods: {
        actionElement(action) {
            if (!action.href || action.disabled) {
                return 'button';
            }

            return action.external ? 'a' : Link;
        },
        actionAttributes(action) {
            if (action.href && !action.disabled) {
                return { href: action.href };
            }

            return { type: 'button', disabled: action.disabled };
        },
    },
};
</script>
